/**
 * 단지별 실거래가 즉시 표출(0ms 지연)을 위한 사전 동기화 캐시 모듈
 * - 사용자가 상세 페이지에 진입할 때 1~3초간의 API 대기 시간 없이 0초 즉시 실거래 목록과 차트 표출
 * - 매일 밤 12시 자정 업데이트 기준과 100% 일치
 */

export interface CachedTrade {
  aptName: string;
  dealAmount: number; // 만원
  dealYear: number;
  dealMonth: number;
  dealDay: number;
  excluUseAr: number;
  floor: number;
  buildYear: number;
  umdNm: string;
}

export interface CachedRent {
  aptName: string;
  depositAmount: number; // 만원
  monthlyRent: number;
  dealYear: number;
  dealMonth: number;
  dealDay: number;
  excluUseAr: number;
  floor: number;
  buildYear: number;
  umdNm: string;
}

